def _SELF005(self, i):
    phase, age = self.state.get("phase", 0), self.state.get("age", 0)
    if not i["Enable"]:
        phase, age = 0, 0
    elif i["Tick"]:
        age += 1
        if age >= (2, 3, 1)[phase]:
            phase, age = (phase + 1) % 3, 0
    self.state.update(phase=phase, age=age)
    return {"Red": phase == 0, "Green": phase == 1, "Amber": phase == 2, "Phase": phase}
